import React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, Trash2, Minus, Plus, ShoppingBag, MessageCircle } from "lucide-react";
import { useCart } from "../context/CartContext";
import { formatPrice } from "../data/products";
import { cartSlide, overlayAnim } from "../utils/animations";

const WHATSAPP_NUMBER = "522411934545";

export default function Cart() {
  const { items, isOpen, closeCart, removeItem, updateQty, totalPrice, clearCart } = useCart();

  const handleWhatsApp = () => {
    if (items.length === 0) return;
    const lines = items.map(
      (i) => `• ${i.name} x${i.quantity} — ${formatPrice(i.price * i.quantity)}`
    );
    const msg = encodeURIComponent(
      `¡Hola! Me gustaría hacer el siguiente pedido:\n\n${lines.join("\n")}\n\nTotal: ${formatPrice(totalPrice)}\n\n¿Está disponible?`
    );
    window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`, "_blank");
    closeCart();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            key="backdrop"
            variants={overlayAnim}
            initial="hidden"
            animate="visible"
            exit="exit"
            onClick={closeCart}
            className="fixed inset-0 z-50 bg-charcoal/50 backdrop-blur-sm"
          />

          {/* Drawer */}
          <motion.aside
            key="drawer"
            variants={cartSlide}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="fixed right-0 top-0 bottom-0 z-50 w-full max-w-sm bg-cream shadow-2xl
                       flex flex-col"
          >
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-5 border-b border-blush">
              <div className="flex items-center gap-2">
                <ShoppingBag size={20} className="text-crimson" />
                <h2 className="font-serif text-xl font-semibold text-charcoal">Tu carrito</h2>
              </div>
              <button
                onClick={closeCart}
                className="p-2 rounded-full hover:bg-blush transition-colors"
                aria-label="Cerrar carrito"
              >
                <X size={20} />
              </button>
            </div>

            {/* Items */}
            <div className="flex-1 overflow-y-auto px-6 py-4">
              <AnimatePresence mode="popLayout">
                {items.length === 0 ? (
                  <motion.div
                    key="empty"
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="h-full flex flex-col items-center justify-center gap-4 text-center py-16"
                  >
                    <div className="w-20 h-20 rounded-full bg-blush flex items-center justify-center text-4xl">
                      🌸
                    </div>
                    <div>
                      <p className="font-serif text-lg text-charcoal font-semibold">Carrito vacío</p>
                      <p className="text-sm text-muted mt-1">Agrega flores para comenzar</p>
                    </div>
                    <button onClick={closeCart} className="btn-primary mt-2">
                      Ver catálogo
                    </button>
                  </motion.div>
                ) : (
                  items.map((item) => (
                    <motion.div
                      key={item.id}
                      layout
                      initial={{ opacity: 0, x: 30 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: -30, height: 0, marginBottom: 0 }}
                      transition={{ duration: 0.25 }}
                      className="flex gap-4 mb-4 bg-white rounded-2xl p-4 shadow-soft"
                    >
                      {/* Thumbnail */}
                      <div className="w-16 h-16 rounded-xl overflow-hidden bg-blush flex-shrink-0">
                        <img
                          src={item.image}
                          alt={item.name}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.target.style.display = "none";
                            e.target.parentNode.innerHTML = "<div class='w-full h-full flex items-center justify-center text-2xl'>🌸</div>";
                          }}
                        />
                      </div>

                      {/* Details */}
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-charcoal text-sm truncate">{item.name}</p>
                        <p className="text-crimson font-bold text-sm mt-0.5">
                          {formatPrice(item.price)}
                        </p>

                        {/* Qty controls */}
                        <div className="flex items-center gap-2 mt-2">
                          <button
                            onClick={() => updateQty(item.id, item.quantity - 1)}
                            className="w-7 h-7 rounded-full bg-blush flex items-center justify-center
                                       hover:bg-dusty/40 transition-colors text-charcoal"
                          >
                            <Minus size={13} />
                          </button>
                          <span className="w-5 text-center text-sm font-bold text-charcoal">
                            {item.quantity}
                          </span>
                          <button
                            onClick={() => updateQty(item.id, item.quantity + 1)}
                            className="w-7 h-7 rounded-full bg-blush flex items-center justify-center
                                       hover:bg-dusty/40 transition-colors text-charcoal"
                          >
                            <Plus size={13} />
                          </button>
                        </div>
                      </div>

                      {/* Remove */}
                      <div className="flex flex-col items-end justify-between">
                        <button
                          onClick={() => removeItem(item.id)}
                          className="p-1.5 text-muted hover:text-crimson hover:bg-petal rounded-lg transition-colors"
                          aria-label="Eliminar"
                        >
                          <Trash2 size={15} />
                        </button>
                        <p className="text-xs font-semibold text-charcoal">
                          {formatPrice(item.price * item.quantity)}
                        </p>
                      </div>
                    </motion.div>
                  ))
                )}
              </AnimatePresence>
            </div>

            {/* Footer */}
            {items.length > 0 && (
              <div className="px-6 py-5 border-t border-blush bg-white/60 backdrop-blur-sm">
                <div className="flex justify-between items-center mb-1">
                  <span className="text-sm text-muted">Subtotal</span>
                  <span className="font-bold text-charcoal">{formatPrice(totalPrice)}</span>
                </div>
                <p className="text-xs text-muted mb-5">
                  Precio de envío coordinado por WhatsApp
                </p>

                <button
                  onClick={handleWhatsApp}
                  className="w-full flex items-center justify-center gap-2 bg-[#25D366] text-white
                             py-3.5 rounded-2xl font-semibold text-sm hover:bg-[#1ebe5d]
                             active:scale-95 transition-all duration-200 shadow-md mb-3"
                >
                  <MessageCircle size={18} />
                  Pedir por WhatsApp
                </button>

                <button
                  onClick={clearCart}
                  className="w-full text-sm text-muted hover:text-crimson transition-colors
                             py-2 text-center"
                >
                  Vaciar carrito
                </button>
              </div>
            )}
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
}
