import React, { useState, useEffect } from "react";
import { motion, AnimatePresence, useScroll, useMotionValueEvent } from "framer-motion";
import { ShoppingBag, Menu, X, Flower } from "lucide-react";
import { useCart } from "../context/CartContext";
import { navbarAnim } from "../utils/animations";

const links = [
  { label: "Catálogo",    href: "#catalogo" },
  { label: "Nosotros",    href: "#nosotros" },
  { label: "Personaliza", href: "#personaliza" },
  { label: "Contacto",    href: "#contacto" },
];

export default function Navbar() {
  const { totalItems, openCart } = useCart();
  const [hidden,    setHidden]   = useState(false);
  const [scrolled,  setScrolled] = useState(false);
  const [menuOpen,  setMenuOpen] = useState(false);
  const { scrollY } = useScroll();

  useMotionValueEvent(scrollY, "change", (latest) => {
    const prev = scrollY.getPrevious() ?? 0;
    setHidden(latest > prev && latest > 80);
    setScrolled(latest > 20);
  });

  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    return () => { document.body.style.overflow = ""; };
  }, [menuOpen]);

  return (
    <>
      <motion.header
        variants={navbarAnim}
        animate={hidden ? "hidden" : "visible"}
        className={`fixed top-0 inset-x-0 z-50 transition-all duration-300 ${
          scrolled ? "bg-cream/95 backdrop-blur-md shadow-soft" : "bg-transparent"
        }`}
      >
        <div className="max-w-7xl mx-auto px-5 md:px-10 h-16 md:h-20 flex items-center justify-between">
          {/* Logo */}
          <a href="#inicio" className="flex items-center gap-2 group">
            <div className="w-8 h-8 bg-crimson rounded-full flex items-center justify-center
                            group-hover:scale-110 transition-transform duration-200">
              <Flower size={16} className="text-white" />
            </div>
            <span className="font-serif text-xl font-semibold text-charcoal tracking-wide">
              Taller<span className="text-crimson"> de Ramos</span>
            </span>
          </a>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-1">
            {links.map((l) => (
              <a
                key={l.href}
                href={l.href}
                className="px-4 py-2 text-sm font-medium text-muted hover:text-crimson
                           rounded-full hover:bg-blush transition-all duration-200"
              >
                {l.label}
              </a>
            ))}
          </nav>

          {/* Actions */}
          <div className="flex items-center gap-3">
            <button
              onClick={openCart}
              className="relative p-2.5 rounded-full hover:bg-blush transition-colors duration-200 group"
              aria-label="Abrir carrito"
            >
              <ShoppingBag size={20} className="text-charcoal group-hover:text-crimson transition-colors" />
              <AnimatePresence>
                {totalItems > 0 && (
                  <motion.span
                    key="badge"
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    exit={{ scale: 0 }}
                    className="absolute -top-0.5 -right-0.5 w-5 h-5 bg-crimson text-white text-[10px]
                               font-bold rounded-full flex items-center justify-center"
                  >
                    {totalItems > 9 ? "9+" : totalItems}
                  </motion.span>
                )}
              </AnimatePresence>
            </button>

            {/* Hamburger */}
            <button
              onClick={() => setMenuOpen((v) => !v)}
              className="md:hidden p-2.5 rounded-full hover:bg-blush transition-colors"
              aria-label="Menú"
            >
              {menuOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>
      </motion.header>

      {/* Mobile menu */}
      <AnimatePresence>
        {menuOpen && (
          <>
            <motion.div
              key="overlay"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setMenuOpen(false)}
              className="fixed inset-0 z-40 bg-charcoal/40 backdrop-blur-sm md:hidden"
            />
            <motion.nav
              key="mobile-menu"
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 30, stiffness: 280 }}
              className="fixed right-0 top-0 bottom-0 z-50 w-72 bg-cream shadow-2xl
                         flex flex-col pt-24 pb-10 px-8 md:hidden"
            >
              <div className="flex flex-col gap-2">
                {links.map((l) => (
                  <a
                    key={l.href}
                    href={l.href}
                    onClick={() => setMenuOpen(false)}
                    className="py-3 border-b border-blush text-lg font-medium text-charcoal
                               hover:text-crimson hover:pl-2 transition-all duration-200"
                  >
                    {l.label}
                  </a>
                ))}
              </div>

              <div className="mt-auto">
                <button
                  onClick={() => { openCart(); setMenuOpen(false); }}
                  className="btn-primary w-full justify-center"
                >
                  <ShoppingBag size={18} />
                  Ver carrito {totalItems > 0 && `(${totalItems})`}
                </button>
              </div>
            </motion.nav>
          </>
        )}
      </AnimatePresence>
    </>
  );
}
