import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ShoppingBag, Check, Heart } from "lucide-react";
import { useCart } from "../context/CartContext";
import { formatPrice } from "../data/products";
import { scaleIn } from "../utils/animations";

const badgeColors = {
  Favorito:  "bg-rose-100 text-rose-600",
  Destacado: "bg-amber-100 text-amber-700",
  Nuevo:     "bg-sage text-green-700",
  Premium:   "bg-petal text-crimson",
  Tendencia: "bg-purple-100 text-purple-600",
};

export default function ProductCard({ product }) {
  const { addItem } = useCart();
  const [added,   setAdded]   = useState(false);
  const [liked,   setLiked]   = useState(false);
  const [imgErr,  setImgErr]  = useState(false);

  const handleAdd = () => {
    addItem(product);
    setAdded(true);
    setTimeout(() => setAdded(false), 1800);
  };

  return (
    <motion.article
      variants={scaleIn}
      whileHover={{ y: -6 }}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
      className="group bg-white rounded-3xl overflow-hidden shadow-card hover:shadow-xl
                 transition-shadow duration-300 flex flex-col"
    >
      {/* Image */}
      <div className="relative overflow-hidden aspect-[4/5] bg-blush">
        {!imgErr ? (
          <img
            src={product.image}
            alt={product.name}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 ease-out"
            onError={() => setImgErr(true)}
          />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center gap-2 bg-gradient-to-br from-blush to-petal">
            <div className="w-16 h-16 rounded-full bg-dusty/30 flex items-center justify-center">
              <span className="text-3xl">🌸</span>
            </div>
            <p className="text-xs text-muted">{product.name}</p>
          </div>
        )}

        {/* Badge */}
        {product.badge && (
          <span className={`absolute top-3 left-3 tag text-xs font-semibold ${badgeColors[product.badge] ?? "bg-warm text-charcoal"}`}>
            {product.badge}
          </span>
        )}

        {/* Wishlist */}
        <motion.button
          whileTap={{ scale: 0.85 }}
          onClick={() => setLiked((v) => !v)}
          className="absolute top-3 right-3 w-9 h-9 bg-white/80 backdrop-blur rounded-full
                     flex items-center justify-center shadow-sm hover:bg-white transition-colors"
          aria-label="Guardar en favoritos"
        >
          <Heart
            size={16}
            className={liked ? "fill-crimson text-crimson" : "text-muted"}
          />
        </motion.button>

        {/* Quick view on hover */}
        <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/20 to-transparent
                        opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
      </div>

      {/* Info */}
      <div className="p-5 flex flex-col gap-3 flex-1">
        <div className="flex-1">
          <p className="text-xs text-muted font-medium uppercase tracking-widest mb-1 capitalize">
            {product.category}
          </p>
          <h3 className="font-serif text-xl text-charcoal font-semibold leading-snug">
            {product.name}
          </h3>
          <p className="text-sm text-muted mt-1.5 leading-relaxed line-clamp-2">
            {product.description}
          </p>
        </div>

        <div className="flex items-center justify-between pt-2 border-t border-blush">
          <p className="font-serif text-2xl font-bold text-charcoal">
            {formatPrice(product.price)}
          </p>

          <motion.button
            whileTap={{ scale: 0.9 }}
            onClick={handleAdd}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-sm font-semibold
                        transition-all duration-300 shadow-sm
                        ${added
                          ? "bg-green-500 text-white shadow-green-200"
                          : "bg-crimson text-white hover:bg-rosewood shadow-dusty/30"
                        }`}
          >
            <AnimatePresence mode="wait">
              {added ? (
                <motion.span
                  key="check"
                  initial={{ scale: 0, rotate: -90 }}
                  animate={{ scale: 1, rotate: 0 }}
                  exit={{ scale: 0 }}
                  className="flex items-center gap-1.5"
                >
                  <Check size={15} strokeWidth={3} /> Añadido
                </motion.span>
              ) : (
                <motion.span
                  key="add"
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  exit={{ scale: 0 }}
                  className="flex items-center gap-1.5"
                >
                  <ShoppingBag size={15} /> Añadir
                </motion.span>
              )}
            </AnimatePresence>
          </motion.button>
        </div>
      </div>
    </motion.article>
  );
}
