import React, { useState } from "react";
import { motion } from "framer-motion";
import { SlidersHorizontal } from "lucide-react";
import { products, categories } from "../data/products";
import ProductCard from "./ProductCard";
import { fadeUp, staggerContainer } from "../utils/animations";

export default function Catalog() {
  const [active, setActive] = useState("todos");

  const filtered = active === "todos"
    ? products
    : products.filter((p) => p.category === active);

  return (
    <section id="catalogo" className="section-padding bg-warm">
      <div className="max-w-7xl mx-auto">

        {/* Header */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          className="text-center mb-12"
        >
          <div className="flex items-center justify-center gap-2 mb-4">
            <span className="h-px w-10 bg-dusty" />
            <span className="tag bg-petal text-crimson text-xs font-semibold uppercase tracking-widest border border-dusty/30">
              Catálogo
            </span>
            <span className="h-px w-10 bg-dusty" />
          </div>
          <h2 className="section-title mb-4">
            Nuestros <span className="text-crimson italic">ramos</span>
          </h2>
          <p className="section-sub mx-auto">
            Cada arreglo es creado con flores frescas seleccionadas a mano.
            Encuentra el ramo perfecto para cada ocasión.
          </p>
        </motion.div>

        {/* Filter tabs */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          className="flex flex-wrap justify-center gap-2 mb-12"
        >
          <SlidersHorizontal size={16} className="text-muted self-center mr-1" />
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActive(cat.id)}
              className={`px-5 py-2 rounded-full text-sm font-semibold border transition-all duration-200 ${
                active === cat.id
                  ? "bg-crimson text-white border-crimson shadow-md"
                  : "bg-white text-muted border-gray-200 hover:border-dusty hover:text-charcoal"
              }`}
            >
              {cat.label}
            </button>
          ))}
        </motion.div>

        {/* Product grid */}
        <motion.div
          key={active}
          variants={staggerContainer}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.1 }}
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
        >
          {filtered.map((product) => (
            <ProductCard key={product.id} product={product} />
          ))}
        </motion.div>

        {/* CTA note */}
        <motion.p
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.5 }}
          className="text-center text-sm text-muted mt-12"
        >
          ¿No encuentras lo que buscas?{" "}
          <a href="#personaliza" className="text-crimson font-semibold hover:underline">
            Personaliza tu ramo
          </a>
        </motion.p>
      </div>
    </section>
  );
}
